<script setup lang="ts">
import RecordList from '@/shared/ui/RecordList.vue'
import {localTime,chinaInput,deadlinePayload} from '@/shared/ui/presentation'
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {currentUser,httpClient} from '@/shared/http/client'
interface Notice {kind?:string;businessNo?:string;reason?:string;id:number;caseId:string;title:string;read:boolean;createdAt:string}
interface Task {taskKey:string;caseId:string;title:string;version:number;deadline:string|null;overdue:boolean}
const route=useRoute(),router=useRouter(),tab=computed(()=>route.query.tab==='notices'?'notices':'todos')
const notices=ref<Notice[]>([]),tasks=ref<Task[]>([]),noticeTotal=ref(0),taskTotal=ref(0),noticePage=ref(1),taskPage=ref(1),busy=ref(false),message=ref(''),selected=ref<Task>(),deadline=ref(''),reason=ref(''),history=ref(''),historyPage=ref(1),historyTotal=ref(0)
const cs=computed(()=>currentUser.value?.roles.includes('CUSTOMER_SERVICE'))
async function run(action:()=>Promise<void>){busy.value=true;message.value='';try{await action()}catch(error){message.value=error instanceof Error?error.message:'操作失败'}finally{busy.value=false}}
async function load(){const inbox=(await httpClient.get<{data:{records:Notice[];total:number}}>('/notifications',{params:{page:noticePage.value,size:20}})).data.data;notices.value=inbox.records;noticeTotal.value=inbox.total;const todo=(await httpClient.get<{data:{records:Task[];total:number}}>('/notifications/todos',{params:{page:taskPage.value,size:20}})).data.data;tasks.value=todo.records;taskTotal.value=todo.total}
async function read(id:number){await httpClient.post(`/notifications/${id}/read`,{});await load()}
function choose(task:Task){selected.value=task;deadline.value=chinaInput(task.deadline);reason.value='';history.value='';historyPage.value=1}
async function save(){if(!selected.value)return;if(!reason.value.trim())throw Error('请填写期限变更原因');selected.value=(await httpClient.post<{data:Task}>('/notifications/deadlines',{taskKey:selected.value.taskKey,expectedVersion:selected.value.version,deadline:deadlinePayload(deadline.value),reason:reason.value})).data.data;message.value='期限变更已留历史；自动提醒未开启';await load()}
async function loadHistory(){if(!selected.value)return;const result=(await httpClient.get<{data:{records:unknown[];total:number}}>('/notifications/deadlines/history',{params:{taskKey:selected.value.taskKey,page:historyPage.value,size:20}})).data.data;history.value=JSON.stringify(result.records,null,2);historyTotal.value=result.total}

onMounted(()=>run(load))
</script>
<template><div class="notifications work-page"><header class="notice-head"><div><p class="eyebrow">INBOX / 站内协作</p><h1>通知与待办</h1><p>期限可留空；逾期仅显示标签，不触发自动升级或短信。</p></div><button :disabled="busy" @click="run(load)">刷新</button></header><nav class="notice-tabs" aria-label="通知分区"><button :aria-current="tab==='todos'?'page':undefined" @click="router.push('/notifications?tab=todos')">我的待办（{{ taskTotal }}）</button><button :aria-current="tab==='notices'?'page':undefined" @click="router.push('/notifications?tab=notices')">站内通知（{{ noticeTotal }}）</button></nav><p role="status" class="message">{{ message }}</p>
<section v-if="tab==='todos'" class="notice-content" aria-label="我的待办"><p v-if="busy&&!tasks.length">正在读取待办…</p><p v-else-if="!tasks.length">暂无待办任务。</p><article v-for="task in tasks" :key="task.taskKey"><div><h2>{{ task.title }}</h2><p>案件 {{ task.caseId }} · {{ task.deadline?`截止 ${localTime(task.deadline)}`:'不限期' }} <strong v-if="task.overdue" class="overdue">已逾期</strong></p></div><div class="row-actions"><button @click="router.push(`/work-orders/${task.caseId}`)">打开案件</button><button v-if="cs" :disabled="busy" @click="choose(task)">设置期限</button></div></article><div class="pager"><button :disabled="busy||taskPage<=1" @click="taskPage--;run(load)">上一页</button><span>第 {{ taskPage }} 页 · 共 {{ taskTotal }} 条</span><button :disabled="busy||taskPage*20>=taskTotal" @click="taskPage++;run(load)">下一页</button></div><div v-if="selected&&cs" class="deadline-editor"><h2>{{ selected.title }} · 期限版本</h2><label>中国时间截止（留空清除）<input v-model="deadline" type="datetime-local"/></label><label>变更原因<textarea v-model="reason" maxlength="2000"/></label><button :disabled="busy" @click="run(save)">保存期限版本</button><button :disabled="busy" @click="run(loadHistory)">查看历史</button><RecordList :value="history"/><div class="pager"><button :disabled="busy||historyPage<=1" @click="historyPage--;run(loadHistory)">历史上一页</button><span>共 {{ historyTotal }} 条</span><button :disabled="busy||historyPage*20>=historyTotal" @click="historyPage++;run(loadHistory)">历史下一页</button></div></div></section>
<section v-else class="notice-content" aria-label="站内通知"><p v-if="busy&&!notices.length">正在读取通知…</p><p v-else-if="!notices.length">暂无站内通知。</p><article v-for="notice in notices" :key="notice.id"><div><h2>{{ notice.title }}</h2><p v-if="notice.kind==='CASE_CANCELLED'">{{ notice.businessNo }} · {{ notice.reason }}</p><p>{{ localTime(notice.createdAt) }} · 案件 {{ notice.caseId }} · {{ notice.read?'已读':'未读' }}</p></div><div class="row-actions"><button @click="router.push(`/work-orders/${notice.caseId}`)">打开案件</button><button :disabled="busy||notice.read" @click="run(()=>read(notice.id))">标记已读</button></div></article><div class="pager"><button :disabled="busy||noticePage<=1" @click="noticePage--;run(load)">上一页</button><span>第 {{ noticePage }} 页 · 共 {{ noticeTotal }} 条</span><button :disabled="busy||noticePage*20>=noticeTotal" @click="noticePage++;run(load)">下一页</button></div></section></div></template>
<style scoped>.notice-head{display:flex;justify-content:space-between;align-items:center;gap:20px}.notice-head h1{margin:4px 0;font-size:26px}.notice-head p:last-child{margin:0}.eyebrow{color:var(--color-accent);font-size:10px;font-weight:700;letter-spacing:.14em}.notice-tabs{display:flex;gap:8px;margin:24px 0}.notice-tabs button[aria-current=page]{background:var(--color-accent);color:#fff}.notice-content{border:1px solid var(--color-border);border-radius:10px;background:#fff}.notice-content article{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 20px;border-bottom:1px solid var(--color-border)}.notice-content h2{margin:0;font-size:15px}.notice-content article p{margin:4px 0 0;font-size:12px}.row-actions{display:flex;gap:8px;flex-wrap:wrap}.pager{display:flex;justify-content:flex-end;align-items:center;gap:12px;padding:16px}.deadline-editor{padding:20px;border-top:1px solid var(--color-border)}.deadline-editor label{display:block;max-width:430px;margin:12px 0}.deadline-editor input,.deadline-editor textarea{display:block;width:100%;margin-top:4px}.notifications button{min-height:36px;padding:7px 12px;border:1px solid var(--color-border);border-radius:6px;background:#fff;color:var(--color-text);cursor:pointer;font:inherit}.notifications button:disabled{opacity:.5;cursor:not-allowed}.notice-head button{align-self:center}.message{color:var(--color-danger)}.overdue{color:#8a5c20}@media(max-width:700px){.notice-content article,.notice-head{align-items:start;flex-direction:column}.row-actions{width:100%}.notice-tabs{flex-wrap:wrap}}</style>
